:root {
  --bg: #0f141b;
  --panel: #1a2230;
  --panel-2: #202b3c;
  --line: #2d3a4f;
  --text: #e6ecf4;
  --muted: #93a2b8;
  --brand: #2f7df6;
  --ok: #2ecc8f;
  --warn: #f5a623;
  --danger: #ef5b5b;
  --radius: 12px;
}

* { box-sizing: border-box; }

body {
  margin: 0;
  font-family: "PingFang SC", "Microsoft YaHei", system-ui, -apple-system, sans-serif;
  background: var(--bg);
  color: var(--text);
  font-size: 14px;
}

#app { min-height: 100vh; }

a { color: var(--brand); cursor: pointer; text-decoration: none; }

.topbar {
  display: flex; align-items: center; gap: 16px;
  padding: 14px 24px;
  background: linear-gradient(90deg, #141c29, #182334);
  border-bottom: 1px solid var(--line);
  position: sticky; top: 0; z-index: 10;
}
.topbar h1 { font-size: 17px; margin: 0; font-weight: 650; letter-spacing: .5px; }
.topbar .badge { font-size: 12px; color: var(--muted); border: 1px solid var(--line);
  padding: 2px 8px; border-radius: 20px; }
.spacer { flex: 1; }

.tabs { display: flex; gap: 8px; }
.tabs button {
